function installStageADetectorSumPatch()
%INSTALLSTAGEADETECTORSUMPATCH Patch Stage A to fit detector-summed ISM.
%
%   Run once from MATLAB:
%
%       installStageADetectorSumPatch
%
%   This modifies calibrateISMFromConfocalSum.m in-place, with a timestamped
%   backup next to it.  The patched Stage-A confocal model becomes the sum of
%   the 23 detector-channel ISM forward model:
%
%       vol(y,x,z) = sum_k normalizedStackAirInterfaceZPlanes(...)(y,x,k,z)
%
%   rather than excitation-only/open-pinhole widefield:
%
%       vol(y,x,z) = I_exc(y,x,z)
%
%   This is the correct observable for the detector-summed frame used for the
%   NA/aberration Stage-A fit.

    target = fullfile(fileparts(mfilename('fullpath')), ...
        'calibrateISMFromConfocalSum.m');
    if exist(target, 'file') ~= 2
        error('installStageADetectorSumPatch:MissingFile', ...
            'Could not find %s', target);
    end

    txt = fileread(target);
    stamp = datestr(now, 'yyyymmdd_HHMMSS');
    backup = [target '.bak_stageA_detector_sum_' stamp];
    fid = fopen(backup, 'w');
    if fid < 0
        error('installStageADetectorSumPatch:BackupFailed', ...
            'Could not create backup %s', backup);
    end
    fwrite(fid, txt);
    fclose(fid);

    txt = patchConfocalAirInterfaceVolume(txt);
    txt = patchSafeExportFigure(txt);

    fid = fopen(target, 'w');
    if fid < 0
        error('installStageADetectorSumPatch:WriteFailed', ...
            'Could not write %s', target);
    end
    fwrite(fid, txt);
    fclose(fid);

    fprintf('Patched Stage A detector-summed ISM model in:\n  %s\n', target);
    fprintf('Backup saved as:\n  %s\n', backup);
end

function txt = patchConfocalAirInterfaceVolume(txt)
    startToken = 'function vol = confocalAirInterfaceVolume(sim, coeffs, planeZ, x0, y0)';
    nextToken = 'function p = clampConfocal';
    i1 = strfind(txt, startToken);
    i2 = strfind(txt, nextToken);
    if isempty(i1) || isempty(i2)
        error('installStageADetectorSumPatch:AnchorNotFound', ...
            'Could not find confocalAirInterfaceVolume or clampConfocal anchors.');
    end
    i1 = i1(1);
    i2 = i2(find(i2 > i1, 1, 'first'));
    if isempty(i2)
        error('installStageADetectorSumPatch:BadAnchorOrder', ...
            'Found anchors in unexpected order.');
    end

    newBlock = [
"function vol = confocalAirInterfaceVolume(sim, coeffs, planeZ, x0, y0)" newline ...
"    % Detector-summed ISM air-interface bead volume.  This is the measured" newline ...
"    % Stage-A observable: sum of the 23 detector scan images, not an ideal" newline ...
"    % excitation-only/open-pinhole widefield approximation.  The finite" newline ...
"    % detector-array collection weighting is therefore included in the NA and" newline ...
"    % aberration fit." newline ...
"    sim = ensureStageADetectorGeometry(sim);" newline ...
"    stack = normalizedStackAirInterfaceZPlanes(sim, coeffs, planeZ, x0, y0, 0);" newline ...
"    vol = squeeze(sum(stack, 3));       % [y x plane], summed over detectors" newline ...
"    if ndims(vol) == 2" newline ...
"        vol = reshape(vol, size(stack,1), size(stack,2), 1);" newline ...
"    end" newline ...
"    total = sum(vol(:));" newline ...
"    if total > 0, vol = vol/total; end" newline ...
"end" newline ...
newline ...
"function sim = ensureStageADetectorGeometry(sim)" newline ...
"    if ~isfield(sim, 'detectorLayout') || isempty(sim.detectorLayout)" newline ...
"        sim.detectorLayout = 'honeycomb23';" newline ...
"    end" newline ...
"    if ~isfield(sim, 'detectorPixelShape') || isempty(sim.detectorPixelShape)" newline ...
"        sim.detectorPixelShape = 'hex';" newline ...
"    end" newline ...
"    if ~isfield(sim, 'detXY') || isempty(sim.detXY)" newline ...
"        [sim.detXY, sim.detectorIndexGrid, sim.detectorLayoutInfo] = ..." newline ...
"            detectorLayout(sim.detectorLayout, sim.detPitch);" newline ...
"    end" newline ...
"    sim.nDet = size(sim.detXY, 1);" newline ...
"    sim.detectorGridSize = size(sim.detectorIndexGrid);" newline ...
"end" newline ...
newline];

    txt = [txt(1:i1-1) char(newBlock) txt(i2:end)];
end

function txt = patchSafeExportFigure(txt)
    txt = strrep(txt, ...
        "exportgraphics(fig, outFile, 'Resolution', 160); close(fig);", ...
        "safeExportFigure(fig, outFile, 160); close(fig);");

    if contains(txt, 'function safeExportFigure(fig, outFile, resolution)')
        return;
    end

    helper = [
newline ...
"function safeExportFigure(fig, outFile, resolution)" newline ...
"    if nargin < 3 || isempty(resolution)" newline ...
"        resolution = 160;" newline ...
"    end" newline ...
"    drawnow;" newline ...
"    try" newline ...
"        exportgraphics(fig, outFile, 'Resolution', resolution);" newline ...
"    catch err" newline ...
"        warning('calibrateISMFromConfocalSum:ExportFallback', ..." newline ...
"            'exportgraphics failed for %s: %s. Falling back to print().', ..." newline ...
"            outFile, err.message);" newline ...
"        drawnow;" newline ...
"        set(fig, 'PaperPositionMode', 'auto');" newline ...
"        print(fig, outFile, '-dpng', sprintf('-r%d', resolution));" newline ...
"    end" newline ...
"end" newline];

    txt = [txt char(helper)];
end
